def feasible(eps, a, b, c, d):
    Ia = (a - eps, a + eps)
    Ib = (b - eps, b + eps)
    Ic = (c - eps, c + eps)
    Id = (d - eps, d + eps)

    # Case: a' = 0 possible
    if Ia[0] <= 0 <= Ia[1]:
        if (Ib[0] <= 0 <= Ib[1]) or (Ic[0] <= 0 <= Ic[1]):
            return True
    # b' = 0
    if Ib[0] <= 0 <= Ib[1]:
        if (Ia[0] <= 0 <= Ia[1]) or (Id[0] <= 0 <= Id[1]):
            return True
    # c' = 0
    if Ic[0] <= 0 <= Ic[1]:
        if (Ia[0] <= 0 <= Ia[1]) or (Id[0] <= 0 <= Id[1]):
            return True
    # d' = 0
    if Id[0] <= 0 <= Id[1]:
        if (Ib[0] <= 0 <= Ib[1]) or (Ic[0] <= 0 <= Ic[1]):
            return True

    # Non-zero case: a'd' = b'c'
    # Try all sign choices (positive/negative intervals)
    # We'll split intervals at zero if needed
    def split_interval(l, r):
        if l >= 0:
            return [(l, r, 1)]  # positive
        if r <= 0:
            return [(l, r, -1)] # negative
        return [(l, 0, -1), (0, r, 1)]

    for al, ar, asign in split_interval(Ia[0], Ia[1]):
        for bl, br, bsign in split_interval(Ib[0], Ib[1]):
            for cl, cr, csign in split_interval(Ic[0], Ic[1]):
                for dl, dr, dsign in split_interval(Id[0], Id[1]):
                    prod1_min, prod1_max = interval_product(al, ar, dl, dr)
                    prod2_min, prod2_max = interval_product(bl, br, cl, cr)
                    if prod1_min <= prod2_max and prod2_min <= prod1_max:
                        return True
    return False

