def interval_product(a, eps):
    lo = a - eps
    hi = a + eps
    return lo, hi

def product_range(a, b, eps):
    corners = [(a-eps)*(b-eps), (a-eps)*(b+eps), (a+eps)*(b-eps), (a+eps)*(b+eps)]
    return min(corners), max(corners)
